changeSet.sql:
INSERT IGNORE INTO role_permissions (role_id, permission_id) SELECT r.id, p.id FROM roles r JOIN permissions p ON p.code IN ('message_template.view', 'message_template.manage') WHERE r.name = 'ADMIN';
INSERT IGNORE INTO role_template_permissions (template_id, permission_id) SELECT t.id, p.id FROM role_templates t JOIN permissions p ON p.code IN ('message_template.view', 'message_template.manage') WHERE t.name = 'ADMIN';
INSERT IGNORE INTO role_assignable_permissions (role_id, permission_id) SELECT r.id, p.id FROM roles r JOIN permissions p ON p.code IN ('message_template.view', 'message_template.manage') WHERE r.name != 'SUPER_ADMIN';
INSERT IGNORE INTO role_template_assignable_permissions (template_id, permission_id) SELECT t.id, p.id FROM role_templates t JOIN permissions p ON p.code IN ('message_template.view', 'message_template.manage') WHERE t.name != 'SUPER_ADMIN';
